<?php
namespace HB\Modules\Matches\Controllers;
use HB\HiddenCMS\Loadables\Controllers\Module as Controller_Module;
class Admin extends Controller_Module
{
	public function index() { return $this->view('admin', ['matches' => $this->model()->all()]); }
	public function add() { return $this->match_form(); } public function _edit($match) { return $this->match_form($match); }
	public function delete($match) { $this->form()->confirm_deletion((string)$this->lang('Deletion'), (string)$this->lang('Delete <b>%s</b>?', utf8_htmlentities($match['title']))); if ($this->form()->is_valid()) { $this->model()->delete_match($match['match_id']); return 'OK'; } return $this->form()->display(); }
	private function match_form($match = [])
	{
		$id = $match['match_id'] ?? 0; $statuses = []; foreach ($this->model()::statuses() as $key => $label) { $statuses[$key] = (string)$this->lang($label); }
		return $this->form2()->rule($this->form_text('title')->title('Title')->value($match['title'] ?? ''))->rule($this->form_select('tournament_id')->title('Tournament')->data($this->model()->tournament_choices())->value($match['tournament_id'] ?? '')->search(1))->rule($this->form_select('home_team_id')->title('Home team')->data($this->model()->team_choices())->value($match['home_team_id'] ?? '')->search(1))->rule($this->form_text('home_name')->title('Home name')->value($match['home_name'] ?? ''))->rule($this->form_select('away_team_id')->title('Away team')->data($this->model()->team_choices())->value($match['away_team_id'] ?? '')->search(1))->rule($this->form_text('away_name')->title('Away name')->value($match['away_name'] ?? ''))->rule($this->form_text('starts_at')->title('Date')->value(substr($match['starts_at'] ?? '', 0, 16)))->rule($this->form_select('status')->title('Status')->data($statuses)->value($match['status'] ?? 'scheduled')->search(0))->rule($this->form_number('best_of')->title('Best of')->value($match['best_of'] ?? 1))->rule($this->form_number('score_home')->title('Home score')->value($match['score_home'] ?? ''))->rule($this->form_number('score_away')->title('Away score')->value($match['score_away'] ?? ''))->rule($this->form_text('stage')->title('Stage')->value($match['stage'] ?? ''))->rule($this->form_number('round_number')->title('Round')->value($match['round_number'] ?? ''))->rule($this->form_text('location')->title('Location')->value($match['location'] ?? ''))->rule($this->form_text('stream_url')->title('Stream URL')->value($match['stream_url'] ?? ''))->rule($this->form_textarea('description')->title('Description')->value($match['description'] ?? ''))->rule($this->form_checkbox('published')->data(['1' => (string)$this->lang('Publish')])->value(!isset($match['published']) || $match['published'] ? ['1'] : []))->submit($id ? (string)$this->lang('Save') : (string)$this->lang('Create'))->back('admin/matches')->success(function($data, $form) use ($id) { try { $this->model()->save($data, $id); redirect('admin/matches'); } catch (\InvalidArgumentException $e) { $form->error(utf8_htmlentities($e->getMessage())); } })->panel();
	}
}
